-- Athena saved query (Product_B2C_Intl)
-- ID: 53668b14-bf20-4919-976b-23f080142255
-- Name: Toilet tag Coverage History Data - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH sl AS ( SELECT mri_session_id, route_id, MAX(op_id) AS operator_id, MAX(__time) AS sl_time FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-07-10 18:30:00' AND __time < TIMESTAMP '2026-07-21 18:30:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' -- AND src_id = 124 GROUP BY 1, 2 ), route_flags AS ( -- Only toilet routes, and only routes that appear in SL SELECT DISTINCT srd.route_id FROM user_interaction.search_route_details srd WHERE srd.__time >= TIMESTAMP '2026-07-10 18:30:00' AND srd.__time < TIMESTAMP '2026-07-21 18:30:00' AND CONTAINS(srd.persuasion_id, '537') AND srd.route_id IN (SELECT DISTINCT route_id FROM sl) ), ui_joined AS ( SELECT sl.operator_id, u.event_src, u.mri_session_id, u.event_group, u.event_name, sl.route_id, CASE WHEN rf.route_id IS NOT NULL THEN 1 ELSE 0 END AS toilet_route_id FROM user_interaction.ui_ux_events u INNER JOIN sl ON sl.mri_session_id = u.mri_session_id AND sl.sl_time BETWEEN u.__time - INTERVAL '1' SECOND AND u.__time + INTERVAL '1' SECOND LEFT JOIN route_flags rf ON rf.route_id = sl.route_id WHERE u.__time >= TIMESTAMP '2026-07-10 18:30:00' AND u.__time < TIMESTAMP '2026-07-21 18:30:00' AND u.header_bu = 'BUS' AND u.header_country = 'IND' AND UPPER(u.event_src) = 'ANDROID' AND ( u.event_group = 'sl_screen_load' OR (u.event_group = 'sl_click_info' AND u.event_name = 'ToiletShown') ) AND ( (UPPER(u.event_src) = 'ANDROID' AND u.app_code >= 821000) OR (UPPER(u.event_src) = 'IOS' AND u.app_code >= 862200) ) ), ui_metrics AS ( SELECT operator_id, event_src, COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' THEN mri_session_id END) AS sl_load_sessions, COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' AND toilet_route_id = 1 THEN mri_session_id END) AS toilet_tag_sl_sessions, COUNT(DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'ToiletShown' THEN mri_session_id END) AS toilet_shown_sl_sessions FROM ui_joined GROUP BY 1, 2 HAVING COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' THEN mri_session_id END) > 0 ), sl_ui_keys AS ( -- Deduped keys so txn join does not explode off UI event rows SELECT DISTINCT operator_id, event_src, mri_session_id, route_id, toilet_route_id FROM ui_joined ), txn_metrics AS ( SELECT k.operator_id, k.event_src, COUNT(DISTINCT bte.tin) AS txn_count, COUNT(DISTINCT CASE WHEN k.toilet_route_id = 1 THEN bte.tin END) AS toilet_tag_tins FROM sl_ui_keys k LEFT JOIN transaction.bus_ticket_events bte ON k.mri_session_id = bte.mri_session_id AND k.route_id = bte.route_id AND bte.event_type = 101 AND bte.country_code = 'IND' AND bte.time_of_event >= TIMESTAMP '2026-07-10 18:30:00' AND bte.time_of_event < TIMESTAMP '2026-07-21 18:30:00' GROUP BY 1, 2 ), coverage AS ( SELECT u.operator_id, u.event_src, u.sl_load_sessions, u.toilet_tag_sl_sessions, u.toilet_shown_sl_sessions, COALESCE(t.txn_count, 0) AS txn_count, COALESCE(t.toilet_tag_tins, 0) AS toilet_tag_tins FROM ui_metrics u LEFT JOIN txn_metrics t ON t.operator_id = u.operator_id AND t.event_src = u.event_src ) SELECT 'Jul 11 to 21' AS doi, c.operator_id, op.travels_full_name, CASE WHEN regexp_like(TRIM(v.assembly_name), '(?i)^RedBus\.Vendor\.') THEN regexp_extract(TRIM(v.assembly_name), '(?i)^RedBus\.Vendor\.(.+)$', 1) ELSE TRIM(v.assembly_name) END AS gds_name, SUM(c.sl_load_sessions) AS sl_load_sessions, SUM(c.toilet_tag_sl_sessions) AS toilet_tag_sl_sessions, SUM(c.toilet_shown_sl_sessions) AS toilet_shown_sl_sessions, SUM(c.txn_count) AS txn_count, SUM(c.toilet_tag_tins) AS toilet_tag_tins FROM coverage c LEFT JOIN lis.operators op ON op.operator_id = c.operator_id LEFT JOIN lis.vendor v ON v.id = op.operator_id GROUP BY 1, 2, 3, 4 ORDER BY 5 DESC, 6 DESC;
